const debug = false;
const sw = 3;
const palettes = [
  ["#855a2d",  "#9dc8b7",  "#f9c323",  "#fef4d0",  "#e7cdab",  "#ed9637",  "#e37925"], // from the picture
	["#000000", "#fd6741", "#f49a7c", "#ffffff", "#278789"], // https://www.color-hex.com/color-palette/5563
	["#eed3a1", "#ab6242", "#cc7e3e", "#b23535", "#e5bb37"] // https://www.color-hex.com/color-palette/22045
];

let palette, strkClr, img;
let blocks = [];

function preload() {
  img = loadImage("file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/default_texture.png");
}

function mousePressed() {
	if (mouseButton === LEFT) setup();
}

function setup() {
  // createCanvas(img.width, img.height);
  createCanvas(innerWidth, innerHeight);
	describe("Mesoamerican colorful grid with pipes and faces ")
  frameRate(60);
  image(img, 0, 0);
  background(128, 192);

	// random palette, 1st run always 1st palette
	palette = Array.from((frameCount === 0) ? palettes[0]: random(palettes));
  if (true || !strkClr) [strkClr] = palette.splice(0, 1); // palette.splice(~~random(palette.length), 1);
  stroke(strkClr);
  strokeWeight(sw);
  describe("Mesoamerican colorful grid with pipes and faces");

	blocks = []
  blocks.push(new Block(0, 0, width, height, random(palette)));
}

function draw() {
  for (let b of blocks) {
    b.show();
  }

	const block = random(blocks.filter((b) => b.t === 0));
	if (block && !block.t) {
		block.subdivide(blocks, palette);
	}
}

function noiseA(palette, val) {
  return palette[~~(noise(val) * palette.length)];
}

class Block {
  constructor(x, y, w, h, c) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.c = c;
    this.t = 0; // t < 0 => can be subdivided
    this.p = {}; // empty params for type
  }

  show() {
    push();
    fill(this.c);
    rect(this.x, this.y, this.w, this.h);

    // vertical stripe
    if (this.t === 1) {
      const s = this.w - 4 * sw;
      const n = ~~(this.h / this.w);
      const d = fract(this.h / this.w) * this.w * 0.5;
      const c1 = noiseA(palette, this.x * this.y);
      const c2 = noiseA(palette, this.x + this.y);
			const f = (~~(this.x + this.y) % 2) ? circle : rect;
			rectMode(CENTER);
      for (let i = 0; i < n; i++) {
        fill(c1);
        f(this.x + this.w * 0.5, d + this.y + this.w * (i + 0.5), s);
        if (s > 8 * sw) {
          fill(c2);
          f(
            this.x + this.w * 0.5,
            d + this.y + this.w * (i + 0.5),
            s * 0.5
          );
        }
      }
    }

    // horizontal stripe
    if (this.t === 2) {
      const s = this.h * 0.8;
      const n = ~~(this.w / this.h);
      const d = fract(this.w / this.h) * this.h * 0.5;
      const c1 = noiseA(palette, this.x * this.y);
      const c2 = noiseA(palette, this.x + this.y);
			const f = (~~(this.x + this.y) % 2) ? circle : rect;
			rectMode(CENTER);
			for (let i = 0; i < n; i++) {
        fill(c1);
        f(d + this.x + this.h * (i + 0.5), this.y + this.h * 0.5, s);
        if (s > 8 * sw) {
          fill(c2);
          f(
            d + this.x + this.h * (i + 0.5),
            this.y + this.h * 0.5,
            s * 0.5
          );
        }
      }
    }

    // is face
    if (this.t === 3) {
      fill(noiseA(palette, this.x * this.y));
      // noFill()
      textAlign(CENTER, CENTER);
      textSize(min(this.w, this.h) / 3);
      const areaRatio = (width * height) / (this.w * this.h);
      /*
      text(
        "face\n" + ~~areaRatio,
        this.x + this.w * 0.5,
        this.y + this.h * 0.5
      );
      */
      rectMode(CENTER);
      const c1 = noiseA(palette, this.x * this.y);
      const c2 = noiseA(palette, this.w * this.h);
      const s = min(this.w, this.h); // * 0.9 - sw;
      const cx = this.x + s/2; // this.w / 2;
      const cy = this.y + s/2; // this.h / 2;
      const es = this.p.es;

			// transform to left/ride or top/bottom edge
      if (this.p.a) {
        if (this.p.r > 1) {
          translate(this.w-this.h, 0)
        } else {
          translate(0, this.h-this.w)
        }
      }

			// head
			fill(c1);
      rect(cx, cy, s, s, s / 10);

			// bäckchen
			if (~~(this.x + this.y) % 2) {
				fill(noiseA(palette, this.x + this.y + this.w + this.h));
				arc(this.x, this.y+s*0.5, s * this.p.mw, s * this.p.mw, PI + HALF_PI, HALF_PI, CHORD)
				arc(this.x + s, this.y+s*0.5, s * this.p.mw, s * this.p.mw, HALF_PI, PI + HALF_PI, CHORD)
			}

			// eyes
      fill(c2);
      ellipse(cx - this.w * 0.15, cy - this.h * 0.2, s*es)
      ellipse(cx + this.w * 0.15, cy - this.h * 0.2, s*es)
      if (s/5 > 5 * sw) {
        fill(c1);
        ellipse(cx - this.w * 0.15, cy - this.h * 0.2, s*es/2-sw)
        ellipse(cx + this.w * 0.15, cy - this.h * 0.2, s*es/2-sw)          
      }

      // mouth: my: random(0.6, 0.7), mw: random(0.5, 0.7), mh: random(0.1, 0.2), mt: random(3), mc: random(palette)
			const mr = sw * 3; // mouse round
			fill(this.p.mc)
      if (this.p.mt === 0) rect(cx, this.y + s * this.p.my, s * this.p.mw, s * this.p.mh, mr, mr, mr, mr )
			if (this.p.mt === 1) rect(cx, this.y + s * this.p.my, s * this.p.mw, s * this.p.mh, 0, 0, mr, mr )
      if (this.p.mt === 2) rect(cx, this.y + s * this.p.my, s * this.p.mw, s * this.p.mh, mr, mr, 0, 0 )
			line(cx - s * this.p.mw * 0.5, this.y + s * this.p.my + this.p.ml * s * this.p.mh,
					 cx + s * this.p.mw * 0.5, this.y + s * this.p.my + this.p.ml * s * this.p.mh)

      // nose nwt: width top, nwd width deviation, nh height
      fill(this.c)
      quad(cx - this.w * this.p.nwt, this.y,
           cx + this.w * this.p.nwt, this.y,
           cx + this.w * (this.p.nwt+this.p.nwd), this.y + s * this.p.nh,
           cx - this.w * (this.p.nwt+this.p.nwd), this.y + s * this.p.nh
      );

      // end face
    }

    // is pipe
    if (this.t === 4) {
      // this.p = {r, n: ~~random(3, 5), c: random(palette)}
      const c1 = noiseA(palette, this.x * this.y);
      const c2 = this.p.c;
      /*
      // noFill()
      textAlign(CENTER, CENTER);
      textSize(min(this.w, this.h) / 3);
      const areaRatio = ((width * height) / (this.w * this.h));
      text("pipe\n" + ~~areaRatio, this.x + this.w * 0.5, this.y + this.h * 0.5);
      */
      if (this.p.r > 1) {
        // horiz
        const n = this.p.n;
        const w = this.w / n;
        for (let i = 0; i < n; i++) {
          const xp = this.x + i * w;
          const yp = this.y;
          const r = noise(xp, yp);
          fill(i % 2 ? c1 : c2);
          rect(xp, yp, w, this.h * r, sw);
          fill(i % 2 ? c2 : c1);
          rect(xp, yp + this.h * r, w, this.h * (1 - r), sw);
        }
      } else {
        // vert
        const n = this.p.n;
        const h = this.h / n;
        for (let i = 0; i < n; i++) {
          const xp = this.x;
          const yp = this.y + i * h;
          const r = noise(xp, yp);
          fill(i % 2 ? c1 : c2);
          rect(xp, yp, this.w * r, h);
          fill(i % 2 ? c2 : c1);
          rect(xp + this.w * r, yp, this.w * (1 - r), h);
        }
      }
    }

    // debug for empty
    if (debug && this.t === 0) {
      fill(noiseA(palette, this.x * this.y));
      // noFill()
      textAlign(CENTER, CENTER);
      textSize(min(this.w, this.h) / 3);
      const areaRatio = (width * height) / (this.w * this.h);
      text(~~areaRatio, this.x + this.w * 0.5, this.y + this.h * 0.5);
    }

    pop();
  }

  subdivide(blocks, palette) {
    // dont subdivide, if has a type
    if (this.t) return false;

    const f = random(0.3, 0.7);
    const r = 4; // some are bigger then others
    let newBlock;

		const splitH = random() < 0.5; // frameCount % 2;
    if (splitH && this.w > width * 0.1) {
      const xx = this.w * f;
      newBlock = new Block(
        this.x + xx,
        this.y,
        this.w - xx,
        this.h,
        random(palette)
      );
      blocks.push(newBlock);
      this.w = xx;
      // inspect if height is b times greater then width
      if (this.w < width * 0.1) {
        if (this.h > r * this.w) {
          this.t = 1;
        } else if (this.h > r * blocks[blocks.length - 1].w) {
          blocks[blocks.length - 1].t = 1;
        }
      }
    } else if (this.h > height * 0.1) {
      const yy = this.h * f;
      newBlock = new Block(
        this.x,
        this.y + yy,
        this.w,
        this.h - yy,
        random(palette)
      );
      blocks.push(newBlock);
      this.h = yy;
      // inspect if width is b times greater then height
      if (this.h < height * 0.1) {
        if (this.w > r * this.h) {
          this.t = 2;
        } else if (this.w > r * blocks[blocks.length - 1].h) {
          blocks[blocks.length - 1].t = 2;
        }
      }
    }

    // check, if faces
    this.checkIsFace();
    if (newBlock) newBlock.checkIsFace();

    // check, if pipes
    this.checkIsPipe();
    if (newBlock) newBlock.checkIsPipe();
  }

  checkIsFace() {
    // dont check, if allready set
    if (this.t) return false;

    const r = this.w / this.h;
    const f = 16;
    if (r > 0.7 && r < 1.42 && f * this.w * this.h < width * height) {
      this.t = 3;
      this.p = { r, a: random() < 0.5, es: random(0.25, 0.4), nwt: random(0.075, 0.125), nwd: random(-0.025, 0.025), nh: random(0.5, 0.75), my: random(0.66, 0.75), mw: random(0.5, 0.7), mh: random(0.1, 0.2), ml: random(-0.2, 0.2), mt: ~~random(3), mc: random(palette) };
    }
  }

  checkIsPipe() {
    // dont check, if allready set
    if (this.t) return false;

    const r = this.w / this.h;
    const f = 64;
    if (r > 0.3 && r < 3.3 && f * this.w * this.h < width * height) {
      this.t = 4;
      this.p = { r, n: ~~random(4, 7), c: random(palette) };
    }
  }
}


// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
